// RISC-V example programs bootable on the RV32IMA console (the riscv32 device).
// Each is a pre-linked image loaded as {entry, segments} into bw-board's
// RiscV32Machine via createDebugTarget('riscv32', {image, config}); its serial
// output reaches the console. `.b64` segments are the ELF's loadable (PT_LOAD,
// file-backed) bytes — .bss is left to the program's own startup to zero, so no
// megabyte of zeros is embedded. `ecallTraps` selects the machine's ECALL
// semantics: FreeRTOS yields via ecall (needs the M-mode trap), RT-Thread does
// not. Built by clang+ld.lld in bw-board (test/fixtures/riscv-*/); see there for
// sources, licences (FreeRTOS MIT, RT-Thread Apache-2.0) and reproducible builds.
//
// This file is generated data — regenerate from the bw-board fixtures if they change.

const b64 = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));

/** @typedef {{id:string,label:string,description:string,entry:number,ecallTraps:boolean,segments:{addr:number,bytes:Uint8Array}[]}} RiscvProgram */

const RAW = {
    hello: {
        label: 'Hello (clang)',
        description: 'A freestanding clang C program: prints a line over the ecall console and exits.',
        entry: 0x1000, ecallTraps: false,
        seg: [
            { addr: 0x1000, b64: 'N4UAAJMFBQATBsABkwgABBMFEABzAAAAkwjQBRMFAABzAAAAZ4AAAA==' },
            { addr: 0x8000, b64: 'SGVsbG8gZnJvbSBjbGFuZyBvbiBSSVNDLVYhCgA=' }
        ]
    },
    freertos: {
        label: 'FreeRTOS',
        description: 'A real FreeRTOS-Kernel V11.1.0 (MIT) image: two tasks interleave (H/L) under the CLINT tick, proving preemptive multitasking.',
        entry: 0x0, ecallTraps: true,
        seg: [
            { addr: 0x0, b64: '' },
            { addr: 0x443c, b64: 'kEQAAKqqqqpARAAA' }
        ]
    },
    rtthread: {
        label: 'RT-Thread Nano',
        description: 'A real RT-Thread Nano V4.1.1 (Apache-2.0) image: the kernel banner, then main() and a worker thread interleave under the tick.',
        entry: 0x0, ecallTraps: false,
        seg: [
            { addr: 0x0, b64: '' },
            { addr: 0x4cf4, b64: 'AQAAAPhMAAD4TAAAeAAAAAIAAAAITQAACE0AACAAAAADAAAAGE0AABhNAAAkAAAACgAAAChNAAAoTQAALAAAAAwAAAA4TQAAOE0AACgAAABETQAARE0AAA==' }
        ]
    }
};

/** The example programs, in menu order. */
export const RISCV_PROGRAMS = Object.entries(RAW).map(([id, p]) => ({
    id, label: p.label, description: p.description, entry: p.entry, ecallTraps: p.ecallTraps,
    segments: p.seg.map(s => ({ addr: s.addr, bytes: b64(s.b64) }))
}));

/** Look up a program by id; falls back to FreeRTOS (the default demonstration). */
export function riscvProgram(id) {
    return RISCV_PROGRAMS.find(p => p.id === id) || RISCV_PROGRAMS.find(p => p.id === 'freertos');
}

export const DEFAULT_RISCV_PROGRAM = 'freertos';
